const STORAGE_KEY = "lumi-language";
const textSources = new WeakMap();
const attributeSources = new WeakMap();
const attributes = ["placeholder", "title", "aria-label"];

function getLanguage() {
  try {
    const value = localStorage.getItem(STORAGE_KEY);
    return Object.hasOwn(STRINGS, value) ? value : "pt-BR";
  } catch { return "pt-BR"; }
}

function localizeText(value, language) {
  if (language === "pt-BR") return value;
  return STRINGS[language][value] || value;
}

function applyTranslations() {
  const language = getLanguage();
  document.documentElement.lang = language;
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const node = walker.currentNode;
    if (node.parentElement?.closest("script,style,textarea,[contenteditable='true'],code,pre")) continue;
    if (!textSources.has(node)) textSources.set(node, node.nodeValue);
    const source = textSources.get(node);
    const trimmed = source.trim();
    if (!trimmed) continue;
    const translated = localizeText(trimmed, language);
    const leading = source.match(/^\s*/)?.[0] || "";
    const trailing = source.match(/\s*$/)?.[0] || "";
    const output = leading + translated + trailing;
    if (node.nodeValue !== output) node.nodeValue = output;
  }

  document.querySelectorAll("[placeholder],[title],[aria-label]").forEach(element => {
    let originals = attributeSources.get(element);
    if (!originals) { originals = {}; attributeSources.set(element, originals); }
    for (const attr of attributes) {
      if (!element.hasAttribute(attr)) continue;
      if (!(attr in originals)) originals[attr] = element.getAttribute(attr);
      const translated = localizeText(originals[attr], language);
      if (element.getAttribute(attr) !== translated) element.setAttribute(attr, translated);
    }
  });

  document.title = language === "en" ? "LUMI — Spaces to connect" : language === "es" ? "LUMI — Espacios para conectar" : "LUMI — Espaços para estar junto";
  const selector = document.getElementById("lumiLanguage");
  if (selector && selector.value !== language) selector.value = language;
}

function ensureLanguageSetting() {
  const settings = document.querySelector(".settings-page");
  if (!settings || document.getElementById("lumiLanguageCard")) return;
  const card = document.createElement("section");
  card.className = "settings-card";
  card.id = "lumiLanguageCard";
  card.innerHTML = '<div class="settings-card-icon material-symbols-rounded">translate</div><div class="settings-card-content"><h2>Idioma</h2><p>Escolha o idioma da interface do LUMI.</p><label class="field-label" for="lumiLanguage">Idioma</label><select class="form-input" id="lumiLanguage"><option value="pt-BR">Português (Brasil)</option><option value="en">Inglês</option><option value="es">Espanhol</option></select></div>';
  const firstCard = settings.querySelector(".settings-card");
  settings.insertBefore(card, firstCard || null);
}

document.addEventListener("change", event => {
  if (event.target?.id !== "lumiLanguage") return;
  const language = Object.hasOwn(STRINGS, event.target.value) ? event.target.value : "pt-BR";
  try { localStorage.setItem(STORAGE_KEY, language); } catch {}
  applyTranslations();
});

const observer = new MutationObserver(() => {
  ensureLanguageSetting();
  applyTranslations();
});
observer.observe(document.body, { childList: true, subtree: true });
ensureLanguageSetting();
applyTranslations();
